154	 * Remove a temporary directory a test made, without failing the test over it.
155	 *
156	 * `rmSync(..., { force: true })` is not enough on Windows, where a directory a git
157	 * process touched stays locked for a moment after that process exits: the removal
158	 * throws `EBUSY`, from a `finally` block, after every assertion in the test has
159	 * already passed. `maxRetries` is exactly what Node added for that.
160	 *
161	 * And it still swallows what survives the retries. This is a temp directory the
162	 * operating system will clean up anyway; a test that cannot delete one has not found
163	 * anything about the code it was testing, and saying it failed would be false.
164	 */
165	export function removeTemp(dir: string): void {
166	  try {
167	    rmSync(dir, { recursive: true, force: true, maxRetries: 10, retryDelay: 50 });
168	  } catch {
169	    // The OS owns it now.
170	  }
