295	export function ghPaginated<T = unknown>(...args: string[]): T[] {
296	  const { code, stdout, stderr } = gh(...args, "--paginate");
297	  if (code !== 0) {
298	    throw new Error(`gh ${args.join(" ")} --paginate: ${stderr || stdout}`);
299	  }
